export const devocionalesPara = (para) => DEVOCIONALES.filter((d) => d.para === para);
export const devocional = (id) => DEVOCIONALES.find((d) => d.id === id);

/** Devocional del día para un destinatario: rota por fecha, así cada día toca uno distinto. */
export function delDia(para, fecha = new Date()) {
  const lista = devocionalesPara(para);
  if (!lista.length) return null;
  const inicio = new Date(fecha.getFullYear(), 0, 0);
  const dia = Math.floor((fecha - inicio) / 86_400_000);
  return lista[dia % lista.length];
}

export function fechaClave(fecha = new Date()) {
  const f = new Date(fecha);
  return `${f.getFullYear()}-${String(f.getMonth() + 1).padStart(2, '0')}-${String(f.getDate()).padStart(2, '0')}`;
}

/** Días seguidos con al menos un devocional hecho para ese destinatario (hasta hoy o ayer). */
export function rachaDevocional(diario, para, hoy = new Date()) {
  const dias = new Set(diario.filter((d) => d.para === para && d.hecho).map((d) => d.fecha));
  const f = new Date(hoy);
  if (!dias.has(fechaClave(f))) f.setDate(f.getDate() - 1);
  let n = 0;
  while (dias.has(fechaClave(f))) { n++; f.setDate(f.getDate() - 1); }
  return n;
}
